/* @lc app=leetcode id=2322 lang=kotlin */ class Solution { fun minimumScore(nums: IntArray, edges: Array<IntArray>): Int = nums.size.let { n -> Array(n) { ArrayList<Int>() }.also { g -> edges.forEach { (a, b) -> g[a].add(b).also { g[b].add(a) } } }.let { g -> IntArray(n).let { par -> IntArray(n).let { tin -> IntArray(n).let { tout -> nums.copyOf().let { xr -> IntArray(1).let { ct -> java.util.ArrayDeque<IntArray>().also { it.addFirst(intArrayOf(0, -1, 0)) }.let { st -> (sequenceOf(0) + generateSequence { st.peekFirst()?.let { f -> if (f[2] < g[f[0]].size) g[f[0]][f[2]++].let { v -> if (v == f[1]) -1 else st.addFirst(intArrayOf(v, f[0], 0)).also { par[v] = f[0] }.let { v * 2 } } else st.pollFirst().let { f[0] * 2 + 1 } } }).filter { it >= 0 }.forEach { e -> (e / 2).let { v -> if (e % 2 == 0) (ct[0]++).let { tin[v] = it } else (ct[0]++).let { tout[v] = it }.also { if (v != 0) xr[par[v]] = xr[par[v]] xor xr[v] } } }.let { nums.fold(0) { a, x -> a xor x }.let { tot -> (1 until n).flatMap { i -> (i + 1 until n).map { j -> i to j } }.minOf { (i, j) -> (if (tin[i] < tin[j] && tout[j] < tout[i]) listOf(xr[j], xr[i] xor xr[j], tot xor xr[i]) else if (tin[j] < tin[i] && tout[i] < tout[j]) listOf(xr[i], xr[j] xor xr[i], tot xor xr[j]) else listOf(xr[i], xr[j], tot xor xr[i] xor xr[j])).let { it.max() - it.min() } } } } } } } } } } } } }